#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int uu_tien = 0, diem_max = 0;
    for (int i = 0; i < n; i++) {
        int s, k;
        scanf("%d %d", &s, &k);
        int d = s * k;
        if (d >= 12) uu_tien++;
        if (d > diem_max) diem_max = d;
    }
    printf("%d %d\n", uu_tien, diem_max);
    return 0;
}
